package dev.eugheist.ttmodern;
final class AwakenedSwordWorldClientAudit {
 static volatile boolean checked;static volatile int targetId=-1;static net.minecraft.world.entity.animal.Cow target;static net.minecraft.world.item.ItemStack held;static int hearts;static boolean saved;
 static void restore(net.minecraft.client.Minecraft mc){if(!saved)return;var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,held);SoulHearts.set(p,hearts);SoulHearts.sync(p);p.inventoryMenu.broadcastChanges();if(target!=null)target.discard();saved=false;}
 static void tick(net.minecraft.client.Minecraft mc,int tick){try{step(mc,tick);}catch(RuntimeException e){mc.getSingleplayerServer().submit(()->restore(mc)).join();throw e;}}
 static void step(net.minecraft.client.Minecraft mc,int tick){
  if(tick==940)mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());held=p.getMainHandItem().copy();hearts=SoulHearts.get(p);saved=true;var sword=new net.minecraft.world.item.ItemStack(AwakenedSword.ITEM.get());AdvancedToolModes.change(sword);AdvancedToolModes.change(sword);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,sword);SoulHearts.set(p,0);SoulHearts.sync(p);p.inventoryMenu.broadcastChanges();target=net.minecraft.world.entity.EntityType.COW.create(p.level());target.setNoAi(true);target.setNoGravity(true);target.setPos(p.getX()+1,p.getY(),p.getZ());p.serverLevel().addFreshEntity(target);targetId=target.getId();});
  if(tick==950){EnchanterClientAudit.check(mc.player.getMainHandItem().is(AwakenedSword.ITEM.get())&&AdvancedToolModes.get(mc.player.getMainHandItem())==2&&SoulHearts.get(mc.player)==0,"sword and initial soul count packet sync");var entity=mc.level.getEntity(targetId);EnchanterClientAudit.check(entity!=null,"native sword target spawn packet");mc.gameMode.attack(mc.player,entity);mc.player.swing(net.minecraft.world.InteractionHand.MAIN_HAND);}
  if(tick==960){EnchanterClientAudit.check(SoulHearts.get(mc.player)==1,"real attack packet and soul payload agree without duplicate client increment");mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());EnchanterClientAudit.check(SoulHearts.get(p)==1&&target.getHealth()<target.getMaxHealth(),"native server soul attack and real damage");SoulHearts.add(p);SoulHearts.add(p);});}
  if(tick==970){EnchanterClientAudit.check(SoulHearts.get(mc.player)==3,"odd soul count network sync");var gui=new net.minecraft.client.gui.GuiGraphics(mc,mc.renderBuffers().bufferSource());SoulHeartsHud.draw(gui,3,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight());gui.flush();mc.getSingleplayerServer().execute(()->{try{checked=true;System.out.println("TT AWAKENED SWORD WORLD CLIENT AUDIT: ALL PASS (real attack and spawn packets,server damage,soul payload/client prediction no duplication,odd-heart native HUD,restored fixture)");}finally{restore(mc);}});}
 }
}
